import SwiftUI
import Foundation

// MARK: - Localization Manager
class LocalizationManager: ObservableObject {
    static let shared = LocalizationManager()
    
    // Current UI language (what the app interface shows in)
    @Published var currentUILanguage: String = "en" {
        didSet {
            loadStringsForCurrentLanguage()
            saveLanguagePreference()
        }
    }
    
    // Target language (what the user is learning)
    @Published var targetLanguage: String = "es"
    
    // All loaded strings for current language
    private var currentStrings: [String: String] = [:]
    
    private init() {
        detectInitialLanguage()
        loadStringsForCurrentLanguage()
    }
    
    // MARK: - Language Detection
    private func detectInitialLanguage() {
        // Debug: Print device languages
        print("🌍 Device preferred languages: \(Locale.preferredLanguages)")
        
        // 1. Get device language first
        let deviceLanguage = Locale.preferredLanguages.first ?? "en"
        let deviceLanguageCode = String(deviceLanguage.prefix(2))
        
        print("🌍 Device language: \(deviceLanguage)")
        print("🌍 Extracted device language code: \(deviceLanguageCode)")
        print("🌍 Device language is supported: \(SupportedUILanguages.isSupported(deviceLanguageCode))")
        
        // 2. Check saved preference
        let savedLanguage = UserDefaults.standard.string(forKey: "app_ui_language")
        print("🌍 Saved language preference: \(savedLanguage ?? "none")")
        
        // 3. Prioritize device language if it's supported and different from saved
        if SupportedUILanguages.isSupported(deviceLanguageCode) {
            if savedLanguage != deviceLanguageCode {
                print("🌍 Device language (\(deviceLanguageCode)) differs from saved (\(savedLanguage ?? "none")), using device language")
                currentUILanguage = deviceLanguageCode
            } else if let saved = savedLanguage {
                print("🌍 Using saved language preference: \(saved)")
                currentUILanguage = saved
            } else {
                print("🌍 No saved preference, using device language: \(deviceLanguageCode)")
                currentUILanguage = deviceLanguageCode
            }
        } else {
            // Device language not supported, fall back to saved or default
            if let saved = savedLanguage, SupportedUILanguages.isSupported(saved) {
                print("🌍 Device language not supported, using saved preference: \(saved)")
                currentUILanguage = saved
            } else {
                print("🌍 Device language not supported and no valid saved preference, defaulting to English")
                currentUILanguage = "en"
            }
        }
        
        print("🌍 Final currentUILanguage: \(currentUILanguage)")
    }
    
    // MARK: - String Loading
    private func loadStringsForCurrentLanguage() {
    currentStrings = LocalizedStrings.getStrings(for: currentUILanguage)
    }
    
    // MARK: - Public Methods
    func getString(_ key: String) -> String {
        return currentStrings[key] ?? key
    }
    
    func getString(_ key: String, arguments: CVarArg...) -> String {
        let template = currentStrings[key] ?? key
        return String(format: template, arguments: arguments)
    }
    
    func changeUILanguage(to languageCode: String) {
        guard SupportedUILanguages.isSupported(languageCode) else { return }
        
        withAnimation(.easeInOut(duration: 0.3)) {
            currentUILanguage = languageCode
        }
    }
    
    func setTargetLanguage(_ languageCode: String) {
        targetLanguage = languageCode
        UserDefaults.standard.set(languageCode, forKey: "target_language")
    }
    
    // Debug method to reset language preference
    func resetLanguagePreference() {
        UserDefaults.standard.removeObject(forKey: "app_ui_language")
        detectInitialLanguage()
        loadStringsForCurrentLanguage()
    }
    
    // Method to check if device language has changed and update accordingly
    func checkDeviceLanguageChange() {
        let deviceLanguage = Locale.preferredLanguages.first ?? "en"
        let deviceLanguageCode = String(deviceLanguage.prefix(2))
        
        print("🌍 Checking device language change: \(deviceLanguageCode) vs current: \(currentUILanguage)")
        
        if SupportedUILanguages.isSupported(deviceLanguageCode) && deviceLanguageCode != currentUILanguage {
            print("🌍 Device language changed to supported language: \(deviceLanguageCode)")
            withAnimation(.easeInOut(duration: 0.3)) {
                currentUILanguage = deviceLanguageCode
            }
        }
    }
    
    private func saveLanguagePreference() {
        UserDefaults.standard.set(currentUILanguage, forKey: "app_ui_language")
    }
    
    // MARK: - RTL Support
    var isRTL: Bool {
        return ["ar", "he", "fa", "ur"].contains(currentUILanguage)
    }
    
    var layoutDirection: LayoutDirection {
        return isRTL ? .rightToLeft : .leftToRight
    }
}

