        "ko": "Tiếng Hàn", "zh": "Tiếng Trung (Giản thể)", /* "zh-Hant": "Tiếng Trung (Phồn thể)", */
        "ar": "Tiếng Ả Rập", "hi": "Tiếng Hindi", "bn": "Tiếng Bengali", /* "bg": "Tiếng Bulgaria",
        "hr": "Tiếng Croatia", "cs": "Tiếng Séc", */ "da": "Tiếng Đan Mạch", "nl": "Tiếng Hà Lan",
        /* "et": "Tiếng Estonia", */ "fi": "Tiếng Phần Lan", /* "el": "Tiếng Hy Lạp", */
        "hu": "Tiếng Hungary", "id": "Tiếng Indonesia", /* "lv": "Tiếng Latvia", "lt": "Tiếng Litva", */
