        "th": "Tiếng Thái", "tr": "Tiếng Thổ Nhĩ Kỳ", "uk": "Tiếng Ukraina", "vi": "Tiếng Việt"
    ]
]
    
    static func languages(for uiLanguage: String = "en") -> [UILanguageInfo] {
        let localizationNames = localizedLanguageNames[uiLanguage] ?? [:]
        
        return baseLanguages.map { lang in
            let localizedName = localizationNames[lang.code] ?? lang.name
            return UILanguageInfo(
                code: lang.code,
                name: localizedName,
                nativeName: lang.nativeName,
                flag: lang.flag
            )
        }
    }
    
    static var allLanguages: [UILanguageInfo] {
        return baseLanguages
    }
    
    static func isSupported(_ code: String) -> Bool {
        return baseLanguages.contains { $0.code == code }
    }
    
    static func getLanguage(_ code: String) -> UILanguageInfo? {
        return baseLanguages.first { $0.code == code }
    }
}

struct UILanguageInfo {
    let code: String
    let name: String
    let nativeName: String
    let flag: String
}

// MARK: - Localized Strings
struct LocalizedStrings {
    static func getStrings(for languageCode: String) -> [String: String] {
        switch languageCode {
        case "es": return SpanishStrings.dictionary
        case "fr": return FrenchStrings.dictionary
        case "de": return GermanStrings.dictionary
        case "it": return ItalianStrings.dictionary
        case "pt": return PortugueseStrings.dictionary
        case "ru": return RussianStrings.dictionary
        case "ja": return JapaneseStrings.dictionary
        case "ko": return KoreanStrings.dictionary
        case "zh": return SimplifiedChineseStrings.dictionary
        // case "zh-Hant": return TraditionalChineseStrings.dictionary // NOT SUPPORTED BY AI SPEECH MODEL
        case "ar": return ArabicStrings.dictionary
        case "hi": return HindiStrings.dictionary
        // case "bg": return BulgarianStrings.dictionary // NOT SUPPORTED BY AI SPEECH MODEL
        // case "hr": return CroatianStrings.dictionary // NOT SUPPORTED BY AI SPEECH MODEL
        // case "cs": return CzechStrings.dictionary // NOT SUPPORTED BY AI SPEECH MODEL
        case "da": return DanishStrings.dictionary
        case "nl": return DutchStrings.dictionary
        // case "et": return EstonianStrings.dictionary // NOT SUPPORTED BY AI SPEECH MODEL
        case "fi": return FinnishStrings.dictionary
        default: return EnglishStrings.dictionary
        }
    }
}

